//! 🧪️ Paid edits preserve authored ordering and deny ungranted turns.
use semio_framework_value_paged_list::{PagedList,PagedListEditCursor,PagedListEditOutcome,PagedListReleaseOutcome,PagedListReservationOutcome};
use semio_framework_value_control_contract::{RetainedCloneProgress,RetainedWorkPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations;
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use serde_json::Value;
fn progress(p:semio_framework_value_paged_list::PagedListProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:usize::from(p.progressed),copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,released_bytes:p.released_allocation_bytes}}
#[test]fn original_paid_edit_keeps_the_item_until_an_admitted_turn(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let(mut list,heap)=observe(||{let mut list=PagedList::<u8,16>::with_page_items(4);for value in law["input"].as_array().unwrap(){list.push(value.as_u64().unwrap()as u8)}list});let mut wallet=Wallet::from_profile(&law["stock"]);let initial=wallet.loan(1,64);wallet.post(RetainedCloneProgress{retained_capacity_bytes:heap.0,..Default::default()},0,initial,heap);let mut bank=EffectBank::new(wallet);let mut input=Some(law["insert"].as_u64().unwrap()as u8);let mut cursor=PagedListEditCursor::insert(law["index"].as_u64().unwrap()as usize,list.len());let denied=bank.loan(1,0);let((poll,actual),heap)=observe(||bank.run(denied,1,|effect|cursor.step(&mut list,&mut input,effect)));let RetainedWorkPoll::Complete(turn)=poll else{panic!("unstarted edit denial remained pending")};assert_eq!(turn.work,0);assert!(matches!(turn.result.unwrap(),PagedListEditOutcome::Denied));assert_eq!(input,Some(9));assert_eq!(list.iter().copied().collect::<Vec<_>>(),vec![1,2]);assert_eq!(actual,None);assert_eq!(heap,(0,0));assert_eq!(bank.take_admitted(),None);bank.post(RetainedCloneProgress::default(),denied,heap);
 for _ in 0..16{if cursor.is_finished(){break}let demand=cursor.step_demand(&list,&input).unwrap();let work=cursor.step_work_demand(&list,&input).unwrap();let grant=bank.loan(1,demand.copy_bytes);let((poll,actual),heap)=observe(||bank.run(grant,work,|effect|cursor.step(&mut list,&mut input,effect)));let RetainedWorkPoll::Complete(turn)=poll else{panic!("synchronous list edit remained pending")};let PagedListEditOutcome::Ready(step)=turn.result.unwrap()else{panic!("quoted edit denied")};let progress=RetainedCloneProgress{copied_items:usize::from(step.progress.progressed),copied_bytes:step.progress.placed_bytes,retained_capacity_bytes:step.progress.allocated_bytes,released_bytes:step.progress.released_allocation_bytes};assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap)}assert!(cursor.is_finished());assert!(input.is_none());assert_eq!(serde_json::to_value(list.iter().copied().collect::<Vec<_>>()).unwrap(),law["expected"]);
 while !list.is_empty(){let grant=bank.loan(1,64);let((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(list.discard_plain_tail(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("discard pending")};assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap(),grant,heap)}while !list.terminal_is_empty(){let copy=list.next_release_copy_byte_demand().unwrap();let depth=list.next_release_depth_demand().unwrap();let bytes=list.next_release_allocation_bytes().unwrap();let mut grant=bank.loan(1,copy);grant.maximum_depth=depth;grant.maximum_release_bytes=bytes;let((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(list.release_empty_page(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("release pending")};let PagedListReleaseOutcome::Ready(step)=turn.result.unwrap()else{panic!("release denied")};assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(RetainedCloneProgress{copied_items:usize::from(step.progressed),copied_bytes:step.placed_bytes,released_bytes:step.released_allocation_bytes,..Default::default()},grant,heap)}
}
#[test]
fn edits_preserve_authored_values_and_zero_grant(){
 let law:Value=serde_json::from_str(include_str!("cases.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){
  let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut list=PagedList::<u64,16>::default();
  for value in row["input"].as_array().unwrap(){while !list.has_reserved_slot(){let grant=bank.loan(1,100000);let (turn,heap)=observe_retirement_allocations(||bank.run(grant,4096,|effect|RetainedWorkPoll::Complete(list.reserve_one(effect))));let (turn,_)=turn;let RetainedWorkPoll::Complete(turn)=turn else{panic!("reservation pending")};let p=match turn.result.unwrap(){PagedListReservationOutcome::Denied=>panic!("funded reservation denied"),PagedListReservationOutcome::Ready(p)=>p};bank.take_admitted();bank.post(progress(p),grant,heap);}list.push_reserved(value.as_u64().unwrap()).unwrap();}
  let mut item=row["item"].as_u64();let index=row["index"].as_u64().unwrap()as usize;let mut cursor=if row["name"]=="insert"{PagedListEditCursor::insert(index,list.len())}else{PagedListEditCursor::remove(index,list.len())};
  let before:Vec<_>=(0..list.len()).map(|i|*list.get(i).unwrap()).collect();let original_item=item;
  for axis in law["denialAxes"].as_array().unwrap(){let mut denied=bank.loan(1,100000);let mut work=4096;match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"copy"=>denied.maximum_copy_bytes=0,"depth"=>denied.maximum_depth=0,"work"=>work=0,_=>panic!("unknown denial axis")};let (turn,heap)=observe_retirement_allocations(||bank.run(denied,work,|effect|cursor.step(&mut list,&mut item,effect)));let (turn,_)=turn;let RetainedWorkPoll::Complete(turn)=turn else{panic!("denied edit pending")};assert!(matches!(turn.result.unwrap(),PagedListEditOutcome::Denied));assert_eq!(turn.work,0);assert_eq!(heap,(0,0));assert_eq!(item,original_item);assert_eq!((0..list.len()).map(|i|*list.get(i).unwrap()).collect::<Vec<_>>(),before);bank.take_admitted();}
  let mut original=before.clone();if let Some(value)=original_item{original.push(value)}original.sort_unstable();
  for _ in 0..law["maximumTurns"].as_u64().unwrap(){if cursor.is_finished(){break}let snapshot=(0..list.len()).map(|i|*list.get(i).unwrap()).collect::<Vec<_>>();let held=item;let mut denied=bank.loan(1,100000);denied.maximum_items=0;let (turn,heap)=observe_retirement_allocations(||bank.run(denied,4096,|effect|cursor.step(&mut list,&mut item,effect)));let (turn,_)=turn;let RetainedWorkPoll::Complete(turn)=turn else{panic!("denied edit pending")};assert!(matches!(turn.result.unwrap(),PagedListEditOutcome::Denied));assert_eq!(turn.work,0);assert_eq!(heap,(0,0));assert_eq!(item,held);assert_eq!((0..list.len()).map(|i|*list.get(i).unwrap()).collect::<Vec<_>>(),snapshot);bank.take_admitted();let grant=bank.loan(1,100000);let (turn,heap)=observe_retirement_allocations(||bank.run(grant,4096,|effect|cursor.step(&mut list,&mut item,effect)));let (turn,_)=turn;let RetainedWorkPoll::Complete(turn)=turn else{panic!("edit pending")};let step=match turn.result.unwrap(){PagedListEditOutcome::Denied=>panic!("funded edit denied"),PagedListEditOutcome::Ready(step)=>step};assert_eq!(u128::from(step.progress.work),turn.work);bank.take_admitted();bank.post(progress(step.progress),grant,heap);let mut current=(0..list.len()).map(|i|*list.get(i).unwrap()).collect::<Vec<_>>();if let Some(value)=item{current.push(value)}current.sort_unstable();assert_eq!(current,original);}
  assert!(cursor.is_finished());let expected:Vec<u64>=serde_json::from_value(row["expected"].clone()).unwrap();assert_eq!((0..list.len()).map(|i|*list.get(i).unwrap()).collect::<Vec<_>>(),expected);if row["name"]=="remove"{assert_eq!(item,Some(before[index]))}else{assert_eq!(item,None)}
 }
}

